/// The pane's cwd, and the two things you want from a path you can see: copy it, or open it
/// (issue #143). Clicking drops the menu; the segment carries a hover well so it reads as clickable
/// (the path and branch segments, which do nothing, deliberately don't).
///
/// A `Menu` with `.menuStyle(.button)` — NOT `.borderlessButton`, which is AppKit-backed and never
/// reports hover, so no `.onHover` fill is possible on it (same reasoning as `ChangesPanel`'s
/// actions menu). No `.fixedSize()` either, unlike the toolbar menus: this label must stay
/// squeezable so `.middle` truncation still fires in a narrow split pane.
///
/// The items are a menu rather than a selectable label because `.textSelection(.enabled)` swallows
/// real mouseDown, which would kill the click this segment now exists to answer.
@ViewBuilder private var cwdSegment: some View {
  if let cwd {
    Menu {
      Button("Copy to Clipboard") {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(cwd, forType: .string)
      }
      // `open`, not `activateFileViewerSelecting`: the cwd IS a directory, so "Open in Finder"
      // means show what's inside it — selecting it in its parent is the answer to "reveal".
      Button("Open in Finder") {
        NSWorkspace.shared.open(URL(fileURLWithPath: cwd, isDirectory: true))
      }
    } label: {
      Label {
        Text(Self.abbreviate(cwd)).truncationMode(.middle)
      } icon: {
        Image(systemName: "folder")
      }
      .labelStyle(.titleAndIcon)
      // Explicit, not inherited: a `Menu`'s label doesn't pick up the bar's ambient
      // `foregroundStyle`, so without this the segment reads brighter than its neighbours.
      .foregroundStyle(theme.tokens.fgMuted)
    }
    .menuStyle(.button)
    .buttonStyle(StatusBarSegmentButtonStyle())
    .menuIndicator(.hidden)
    .help(cwd)
    .accessibilityLabel("Working directory \(cwd)")
    .accessibilityIdentifier("terminal.statusBar.cwd")
  }
}

